import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.Collections;

public class Main {
    // Leitor rápido para lidar eficientemente com N até 10^5
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) c = readByte();
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }

    static class Element implements Comparable<Element> {
        int height;
        int index;

        Element(int height, int index) {
            this.height = height;
            this.index = index;
        }

        @Override
        public int compareTo(Element o) {
            return Integer.compare(o.height, this.height); // Ordem decrescente
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n <= 0) {
            System.out.println(1);
            return;
        }

        int[] rawA = new int[n];
        for (int i = 0; i < n; i++) {
            rawA[i] = scanner.nextInt();
        }

        // Remove duplicatas adjacentes
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (m == 0 || rawA[i] != rawA[i - 1]) {
                rawA[m++] = rawA[i];
            }
        }

        Element[] elements = new Element[m];
        for (int i = 0; i < m; i++) {
            elements[i] = new Element(rawA[i], i);
        }

        // Ordena por altura em ordem decrescente
        Arrays.sort(elements);

        boolean[] active = new boolean[m];
        int currentComponents = 0;
        int maxComponents = 0;

        int i = 0;
        while (i < m) {
            int j = i;
            // Agrupa todos os elementos de mesma altura
            while (j < m && elements[j].height == elements[i].height) {
                int idx = elements[j].index;
                boolean left = (idx > 0 && active[idx - 1]);
                boolean right = (idx < m - 1 && active[idx + 1]);

                if (!left && !right) {
                    currentComponents++;
                } else if (left && right) {
                    currentComponents--;
                }
                // Se apenas um vizinho estiver ativo, currentComponents não muda

                j++;
            }

            // Marca todos do grupo atual como ativos
            for (int k = i; k < j; k++) {
                active[elements[k].index] = true;
            }

            if (currentComponents > maxComponents) {
                maxComponents = currentComponents;
            }

            i = j;
        }

        // O resultado é o máximo de componentes superiores + 1 (a base)
        System.out.println(maxComponents + 1);
    }
}
