    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;

    // Leitura das alturas e compressão de elementos adjacentes iguais
    const a = [0]; // borda esquerda com 0
    for (let i = 0; i < n; i++) {
        const val = readInt();
        if (a[a.length - 1] !== val) {
            a.push(val);
        }
    }
    a.push(0); // borda direita com 0

    const m = a.length - 2; // número de elementos úteis (índices 1 a m)

    // Agrupar índices por altura
    // Usamos um array de índices e ordenamos por altura decrescente
    const indices = new Int32Array(m);
    for (let i = 0; i < m; i++) {
        indices[i] = i + 1;
    }

    indices.sort((i, j) => a[j] - a[i]);

    const present = new Uint8Array(a.length);
    let currentComponents = 0;
    let maxComponents = 0;

    let p = 0;
